const EventEmitter = require('node:events');
const inventoryEmitter = new EventEmitter();

// Listener for inventory changes
inventoryEmitter.on('update', (item) => {
  // Asynchronously update database record
  console.log(`Updating ${item.id} to ${item.count}`);
});

// Triggering an event without blocking the main thread
inventoryEmitter.emit('update', { id: 'SKU123', count: 5 });
